"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["60341"],{5579(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>d,contentTitle:()=>p,toc:()=>h,assets:()=>c});var i=JSON.parse('{"id":"nhcx/v1/api/onboarding/endpoints/onboarding-update-validate","title":"Validate participant update","description":"Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.","source":"@site/docs/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate.mdx","sourceDirName":"nhcx/v1/api/onboarding/endpoints","slug":"/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate","permalink":"/docs/main/docs/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Validate participant update","sidebar_label":"Validate participant update","sidebar_class_name":"api-method api-method--get","description":"Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-onboarding.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Validate participant creation","permalink":"/docs/main/docs/nhcx/v1/api/onboarding/endpoints/onboarding-validate"},"next":{"title":"Overview","permalink":"/docs/main/docs/nhcx/v1/api/adjudicator/"}}'),n=a(62540),r=a(43023),s=a(44136),o=JSON.parse('{"id":"onboarding_update_validate","module":"Onboarding","moduleId":"onboarding","kind":"operation","method":"GET","path":"/update/validate","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Validate participant update","description":"Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.\\n\\n### Business purpose\\n\\nChanging a participant\'s encryption certificate or callback endpoint changes where encrypted claims data is delivered and who can decrypt it, so the registry does not apply such updates on an API call alone. /v2/participant/update stages the change and sends a passcode to the registered mobile number; this call confirms it. It is step 4 of the production onboarding sequence and the same approval mechanism protects every later certificate or bridge rotation done through the v2 update.\\n\\n### When to use\\n\\nCall it after /v2/participant/update returns a transactionid and the passcode arrives by SMS, within the 24-hour validity window. The production URL is https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=\\"\\"&passcode=\\"\\". It is also the closing step of the annual key-rotation checklist when rotation is done via /v2/participant/update. The passcode-free alternative for certificate-only changes is /v2/update/cert. No workflow or x-hcx-status codes apply.\\n\\n### Preconditions\\n\\n- The participant is already registered and its creation was confirmed via /validate.\\n- A completed /v2/participant/update that returned a transactionid, with the matching passcode received on the registered mobile number.\\n- The call is made within 24 hours; each new update trigger generates a new transaction id and passcode.\\n- Bearer token with the Bearer prefix in bearer_auth and Accept: application/json; parameters go in the query string.\\n\\n### Postconditions\\n\\nHTTP 200 with a bare string body (operation particiapntUpdateValidate, response type string). The staged certificate and endpoint URL become the participant\'s live registry values, which is what counterparties will receive from /fetch/certs and what the gateway will use for callback delivery. There is no asynchronous callback. Errors return the registry ErrorResponse envelope with 400, 404 or 500.\\n\\n### Common mistakes\\n\\n- Assuming the update is live as soon as /v2/participant/update returns; until this call succeeds counterparties may still fetch the old certificate.\\n- Presenting a passcode from a previous update attempt after a new one was triggered.\\n- Letting the 24-hour window lapse and then retrying validation instead of re-issuing the update.\\n- Calling /validate (creation) instead of /update/validate.\\n- Losing the transaction id, which requires repeating the update request.\\n\\n### Best practices\\n\\n- Rotate keys in two phases: keep the old private key available for decrypting inbound callbacks until the update is validated and cached certificates (24-hour TTL on the payer side) have refreshed.\\n- Persist transactionid with its 24-hour expiry and record who completed validation, for audit.\\n- Never log the passcode; treat it as a one-time credential.\\n- After success, call /participant/search on your own code to confirm encryption_cert and endpoint_url reflect the change.\\n\\n### Related scenario\\n\\nA year after go-live a payer\'s security team rotates the encryption key pair. The integrator generates a new self-signed X.509 certificate, Base64-encodes it and calls /v2/participant/update with participantcode and encryptioncert. The registry returns status and a new transactionid and sends a passcode to the registered mobile. Within the hour the team calls GET /update/validate with both values; on 200 the new certificate is live. Providers that cached the old certificate pick up the new one at their next 24-hour refresh, and the payer keeps the old private key for one more day to decrypt in-flight callbacks.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[{"name":"transactionId","required":true,"description":"","type":"string"},{"name":"passcode","required":true,"description":"","type":"string"}],"body":[],"responses":[{"status":"200","description":"HTTP 200 with a bare string body (operation particiapntUpdateValidate, response type string).","example":{"_contentType":"string","_body":"<confirmation string as declared by the OpenAPI 200 response>"}}],"tag":"Onboarding","tagDescription":"Nothing moves through NHCX until both the sender and the recipient exist in the participant registry, which the platform treats as the source of truth for who may exchange claims data.","curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/validate \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/validate \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/validate\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/validate\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let d={title:"Validate participant update",sidebar_label:"Validate participant update",sidebar_class_name:"api-method api-method--get",description:"Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-onboarding.yaml",generated:!0},p,c={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);